    function run(uint _minSum) public payable {
        c.SetMinSum(_minSum); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        uint afterInitMinSum = c.MinSum(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.SetMinSum(_minSum == type(uint256).max ? 0 : _minSum + 1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }
