pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function _run(uint256 _minSum) internal {
        try c.SetMinSum(_minSum) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 afterInitMinSum;
        try c.MinSum() returns (uint256 __r) { afterInitMinSum = __r; } catch { return; }
        bool reverted;
        try c.SetMinSum(_minSum == type(uint256).max ? 0 : _minSum + 1) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && afterInitMinSum == _minSum && c.MinSum() == afterInitMinSum);
    }

    function testFuzz_run(uint256 _minSum) public {
        _run(_minSum);
    }

    receive() external payable {}
}
